import csv, statistics
def load(tid):
    d={}
    for row in csv.DictReader(open(VALUES_CSV)):
        if row["timeseries_id"]==tid: d[row["timestamp"]]=float(row["value"])
    return d

# F3 sensor, F3 damper, F2 sensor, F2 damper, F4 sensor, F4 damper
F3s=load("e0dd5f44-f050-5faa-a2a0-a3fcb6284ae8")
F3v=load("de92aecc-fc37-5d28-a0b6-fb34b4c34747")
F2s=load("baef86cb-2941-5d61-87b0-ffa91d79f23a")
F2v=load("793c9605-4c68-5b90-8747-faffb8666e4b")
F4s=load("14a08406-79a0-52ca-b8a1-8563259dc820")
F4v=load("d3e3a9f8-b070-5082-8bc6-c54900258c1a")

def stats(d,lo,hi):
    v=[x for t,x in d.items() if lo<=t<hi]
    return round(statistics.mean(v),2), round(statistics.pstdev(v),3)
for n,d in [("F3s",F3s),("F2s",F2s),("F4s",F4s),("F3v",F3v),("F2v",F2v),("F4v",F4v)]:
    print(n,"H1 mean/sd",stats(d,"2018-01-01","2018-07-01")," H2",stats(d,"2018-07-01","2019-01-01"))

# correlation zone sensor to own damper (load response) H1 vs H2
def corr(d1,d2,lo,hi):
    xs=[];ys=[]
    for t in d1:
        if lo<=t<hi and t in d2: xs.append(d1[t]); ys.append(d2[t])
    mx=statistics.mean(xs);my=statistics.mean(ys)
    cov=sum((a-mx)*(b-my) for a,b in zip(xs,ys))
    return round(cov/((sum((a-mx)**2 for a in xs))**.5*(sum((b-my)**2 for b in ys))**.5),3)
for n,s,v in [("F3",F3s,F3v),("F2",F2s,F2v),("F4",F4s,F4v)]:
    print(n,"sensor-vs-own-damper H1",corr(s,v,"2018-01-01","2018-07-01"),"H2",corr(s,v,"2018-07-01","2019-01-01"))
